.liquid-surface {
  --liquid-blur: 20px;
  --liquid-tint: .22;
  --liquid-ink: #172323;
  --liquid-fill: 255 255 255;
  position: relative;
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / var(--liquid-tint));
  border: 1px solid rgb(255 255 255 / .65);
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  box-shadow: inset 0 1px 1px rgb(255 255 255 / .9), inset 0 -1px 1px rgb(255 255 255 / .25), inset 2px 0 5px rgb(255 255 255 / .18), 0 8px 28px rgb(0 20 25 / .14);
  transition: background 200ms ease, box-shadow 200ms ease;
}
.liquid-surface:focus-visible, .liquid-tab:focus-visible, .liquid-toolbar-button:focus-visible { outline: 3px solid #007aff; outline-offset: 4px; }
.liquid-interactive {
  position: relative;
  isolation: isolate;
  translate: var(--liquid-x, 0px) var(--liquid-y, 0px);
  scale: var(--liquid-scale-x, 1) var(--liquid-scale-y, 1);
  /* The spring owns translate/scale; consumers still own transform. */
  transition: background 200ms ease, box-shadow 200ms ease, opacity 140ms ease;
}
/* Pointer light. Pressing floods the glass with light as it swells toward the finger. */
.liquid-interactive::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(ellipse at var(--liquid-light-x, 50%) var(--liquid-light-y, 25%), rgb(255 255 255 / calc(.48 + .32 * var(--liquid-press, 0))), rgb(255 255 255 / calc(.07 + .2 * var(--liquid-press, 0))) 45%, transparent 72%);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / calc(.28 + .42 * var(--liquid-press, 0))), inset 0 0 calc(16px * var(--liquid-press, 0)) rgb(255 255 255 / calc(.5 * var(--liquid-press, 0)));
  opacity: var(--liquid-light, 0);
  z-index: -1;
}
/* Content morph: new content condenses out of light while the width springs. */
.liquid-interactive[data-liquid-morphing] { overflow: clip; }
.liquid-interactive[data-liquid-morph="a"] { animation: liquid-ink-in-a 420ms cubic-bezier(.2, .8, .2, 1); }
.liquid-interactive[data-liquid-morph="b"] { animation: liquid-ink-in-b 420ms cubic-bezier(.2, .8, .2, 1); }
.liquid-interactive[data-liquid-morph="a"] > svg { animation: liquid-glyph-in-a 480ms cubic-bezier(.2, .9, .25, 1.25); }
.liquid-interactive[data-liquid-morph="b"] > svg { animation: liquid-glyph-in-b 480ms cubic-bezier(.2, .9, .25, 1.25); }
@keyframes liquid-ink-in-a { from { color: transparent; text-shadow: 0 0 12px rgb(255 255 255 / .95); } }
@keyframes liquid-ink-in-b { from { color: transparent; text-shadow: 0 0 12px rgb(255 255 255 / .95); } }
@keyframes liquid-glyph-in-a { from { opacity: 0; filter: blur(5px); scale: .45; } }
@keyframes liquid-glyph-in-b { from { opacity: 0; filter: blur(5px); scale: .45; } }
.liquid-button { border-radius: 999px; min-height: 44px; font-weight: 600; padding-inline: 24px; }
.liquid-button:hover:not(:disabled) { background: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + .1)); box-shadow: inset 0 1px 2px white, inset 0 -1px 2px rgb(190 224 255 / .5), 0 12px 32px rgb(0 20 25 / .2); }
.liquid-button[data-size^="icon"] { padding-inline: 0; min-width: 44px; }
.liquid-button[data-liquid-variant="destructive"] { --liquid-ink: #a20c22; --liquid-fill: 255 200 208; }
.liquid-button[data-liquid-variant="ghost"], .liquid-button[data-liquid-variant="link"] { border-color: transparent; box-shadow: none; background: transparent; backdrop-filter: none; }
.liquid-button[data-liquid-variant="link"] { text-decoration: underline; }
.liquid-button[data-liquid-variant="secondary"] { background: rgb(var(--liquid-fill) / .55); }
.liquid-button[data-state="open"] > svg { rotate: 180deg; }
.liquid-button > svg { transition: rotate 350ms cubic-bezier(.2,.8,.2,1); }

/* Segmented tabs and toolbars share one lens. */
.liquid-tabs { border-radius: 999px; padding: 5px; height: 52px; gap: 3px; isolation: isolate; touch-action: pan-y; -webkit-user-select: none; user-select: none; -webkit-touch-callout: none; transition: background 200ms ease, box-shadow 200ms ease, scale 460ms cubic-bezier(.25, 1.45, .45, 1); }
.liquid-tabs[data-orientation="vertical"] { height: auto; border-radius: 26px; touch-action: pan-x; }
/* The whole bar swells a little while a finger is on it. */
.liquid-tabs[data-liquid-pressed] { scale: 1.025; transition-duration: 200ms, 200ms, 240ms; }
.liquid-tab { position: relative; color: var(--liquid-ink); border-radius: 999px; padding-inline: 22px; height: 40px; background: transparent; transition: color 180ms ease; }
.liquid-tab[data-state="active"] { color: var(--liquid-ink); background: rgb(var(--liquid-fill) / .58); box-shadow: 0 2px 8px rgb(0 0 0 / .12), inset 0 1px 1px rgb(255 255 255 / .8); }
.liquid-tabs[data-liquid-indicator] .liquid-tab[data-state="active"] { background: transparent; box-shadow: none; }
.liquid-tab:hover:not(:disabled) { color: var(--liquid-ink); }
.liquid-lens {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  overflow: hidden;
  border-radius: 999px;
  pointer-events: none;
  /* At rest: a frosted pill. Lifted: clear glass with a bright, faintly chromatic rim. */
  background:
    linear-gradient(135deg, rgb(255 255 255 / calc(.2 * (1 - var(--liquid-lift, 0)))), transparent 55%),
    rgb(var(--liquid-lens-fill, 255 255 255) / calc(var(--liquid-lens-alpha, .5) * (1 - .8 * var(--liquid-lift, 0))));
