    to(next: number[], immediate = false, feel = .5) {
      target = [...next];
      viscosity = Math.max(0, Math.min(1, feel));
      if (immediate) {
        cancelAnimationFrame(frame);
        frame = 0;
        values = [...target];
        velocity.fill(0);
        render(values, velocity);
      } else if (!atRest()) start();
    },
